 <body>
   <main class="support-card">
     <p class="eyebrow">Support</p>
     <h1>Contact our team</h1>
     <p class="subtitle">Send us a message and we will get back to you as soon as possible.</p>

     <form id="contact-form" novalidate>
       <div class="form-field" data-field="name">
         <label for="full-name">Full name</label>
         <input id="full-name" name="fullName" type="text" autocomplete="name" required />
         <div class="error-text" id="name-error" aria-live="polite"></div>
       </div>

       <div class="form-field" data-field="email">
         <label for="email-address">Email address</label>
         <input id="email-address" name="email" type="email" autocomplete="email" required />
         <div class="error-text" id="email-error" aria-live="polite"></div>
       </div>

       <div class="form-field" data-field="phone">
         <label for="phone-number">Phone number</label>
         <input
           id="phone-number"
           name="phone"
           type="text"
           inputmode="tel"
           autocomplete="tel"
           aria-describedby="phone-help phone-error"
           placeholder="+1 555 123 4567"
         />
         <div class="helper-text" id="phone-help">Use a format like +1 555 123 4567 or 555-123-4567.</div>
         <div class="error-text" id="phone-error" aria-live="polite"></div>
       </div>

       <div class="actions">
         <button type="submit">Submit</button>
       </div>

       <div class="status" id="form-status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('contact-form');
     const status = document.getElementById('form-status');

     const fields = {
       name: {
         input: document.getElementById('full-name'),
         error: document.getElementById('name-error'),
         wrapper: document.querySelector('[data-field="name"]'),
         message: 'Please enter your full name.'
       },
       email: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-error'),
         wrapper: document.querySelector('[data-field="email"]'),
         message: 'Please enter a valid email address.'
       },
       phone: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-error'),
         wrapper: document.querySelector('[data-field="phone"]'),
         message: 'Please enter a phone number in the expected format.'
       }
     };

     const phonePattern = /^(?:\+?\d{1,3}[\s-]?)?(?:\(?\d{3}\)?[\s-]?)\d{3}[\s-]?\d{4}$/;

     const setFieldState = (field, invalid, message = '') => {
       field.wrapper.classList.toggle('is-invalid', invalid);
       field.input.setAttribute('aria-invalid', invalid ? 'true' : 'false');
       field.error.textContent = message;
     };

     const validateName = () => fields.name.input.value.trim().length > 0;
     const validateEmail = () => fields.email.input.validity.valid && fields.email.input.value.trim().length > 0;
     const validatePhone = () => {
       const value = fields.phone.input.value.trim();
       return value === '' || phonePattern.test(value);
     };

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const isNameValid = validateName();
       const isEmailValid = validateEmail();
       const isPhoneValid = validatePhone();

       setFieldState(fields.name, !isNameValid, isNameValid ? '' : fields.name.message);
       setFieldState(fields.email, !isEmailValid, isEmailValid ? '' : fields.email.message);
       setFieldState(fields.phone, !isPhoneValid, isPhoneValid ? '' : fields.phone.message);

       if (!isNameValid || !isEmailValid || !isPhoneValid) {
         status.textContent = '';
         return;
       }

       status.textContent = 'Thanks — your message is ready to send.';
       form.reset();
       Object.values(fields).forEach((field) => setFieldState(field, false));
     });
   </script>
